            I*r^3*(3 + lambda)*omega + r^4*omega^2) - 2*I*a^3*m*r^3*(13 + r*(-17 + 2*lambda) + 
            r^2*(6 + m^2 - 2*lambda - 2*I*omega) - 3*I*r^3*(2 + lambda)*omega + 3*r^4*omega^2) + 
