# W(r) in U S^2 = -K^2 + Delta W (U = sU, S = r^2 + a^2, K = S omega - a m, Delta = r^2 - 2r + a^2), from
# sU above with SymPy: numerator of U S^2 + K^2 divided exactly by Delta in r; numerator and denominator
# in Horner form in t = r - 1 (W is used near the horizon, r ~ 1), each coefficient in Horner form in lambda
# (2.7e-13 -> 1e-13 relative at (-2,3,3,0.99,1.6987), 4e-14 -> 1e-15 at (-2,2,2,0.95,0.785)).
function sW(s::Int, m::Int, a, omega, lambda, r)
    t = r - 1
    if s == 0
        return ((((((((((lambda))*t + (8 * lambda + 2))*t + (a^2 + lambda*(4 * a^2 + 28) + 14))*t + (6 * a^2 + lambda*(24 * a^2 + 56) + 42))*t + (a^2*(3 * a^2 + 15) + lambda*(a^2*(6 * a^2 + 60) + 70) + 70))*t + (a^2*(6 * a^2 + 20) + lambda*(a^2*(24 * a^2 + 80) + 56) + 70))*t + (a^2*(3 * a^4 + 15) + lambda*(a^2*(a^2*(4 * a^2 + 36) + 60) + 28) + 42))*t + (a^2*(a^2*(2 * a^2 - 6) + 6) + lambda*(a^2*(a^2*(8 * a^2 + 24) + 24) + 8) + 14))*t + (a^2*(a^2*(a^2*(a^2 - 1) - 3) + 1) + lambda*(a^2*(a^2*(a^2*(a^2 + 4) + 6) + 4) + 1) + 2)) /
            ((((((((((1))*t + (8))*t + (4 * a^2 + 28))*t + (24 * a^2 + 56))*t + (6 * a^4 + 60 * a^2 + 70))*t + (24 * a^4 + 80 * a^2 + 56))*t + (4 * a^6 + 36 * a^4 + 60 * a^2 + 28))*t + (8 * a^6 + 24 * a^4 + 24 * a^2 + 8))*t + (a^8 + 4 * a^6 + 6 * a^4 + 4 * a^2 + 1))
